class Solution {
    private int pos = 0;

    public String decodeString(String s) {
        StringBuilder sb = new StringBuilder();

        while (pos < s.length() && s.charAt(pos) != ']') {
            char c = s.charAt(pos);
            if (Character.isDigit(c)) {
                // 读完整数字，可能是多位
                int num = 0;
                while (pos < s.length() && Character.isDigit(s.charAt(pos))) {
                    num = num * 10 + (s.charAt(pos) - '0');
                    pos++;
                }
                pos++;                    // 跳过 '['
                String inner = decodeString(s);   // 递归解析内部
                pos++;                    // 跳过配对的 ']'
                for (int k = 0; k < num; k++) sb.append(inner);
            } else {
                sb.append(c);
                pos++;
            }
        }
        return sb.toString();
    }
}

import java.util.*;

class Solution {
    public String decodeString(String s) {
        Deque<Integer> countStack = new ArrayDeque<>();
        Deque<StringBuilder> strStack = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();
        int num = 0;

        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');   // 多位数
            } else if (c == '[') {
                countStack.push(num);
                num = 0;
                strStack.push(sb);              // 暂存外层已拼好的部分
                sb = new StringBuilder();       // 开始装内层
            } else if (c == ']') {
                int k = countStack.pop();
                StringBuilder prev = strStack.pop();
                String inner = sb.toString();
                sb = new StringBuilder(prev);   // 回到外层
                for (int i = 0; i < k; i++) sb.append(inner);
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

import java.util.*;

class Solution {
    public String decodeString(String s) {
        StringBuilder sb = new StringBuilder();
        // 栈里存 [重复次数, 内容在 sb 中的起始位置]
        Deque<int[]> stack = new ArrayDeque<>();
        int num = 0;

        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            } else if (c == '[') {
                // 记录当前 sb 长度，即 [ 内部内容的起点
                stack.push(new int[]{num, sb.length()});
                num = 0;
            } else if (c == ']') {
                int[] top = stack.pop();
                int k = top[0], start = top[1];
                String inner = sb.substring(start);   // 必须先取内容
                sb.setLength(start);                  // 再截断
                for (int i = 0; i < k; i++) sb.append(inner);
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}
